<script setup lang="ts">
import {newStoreId} from '~/shared/cms/store-location.mjs'
import {firstImage,rowName} from '~/shared/cms/workflow.mjs'
const props=defineProps<{modelValue:any;schema:any;label?:string;path?:string;documentId?:string}>()
const emit=defineEmits<{'update:modelValue':[value:any]}>()
const search=ref(''),page=ref(1),picker=ref(false),openIndex=ref<number|null>(null),root=ref<HTMLElement>()
const title=computed(()=>props.schema.label||'內容項目'),hintId=useId(),errors=inject<any>('cms-field-errors',ref([]))
const fieldError=computed(()=>errors.value?.find((e:any)=>e.documentId===props.documentId&&e.path===(props.path||'').replace(/^\./,''))?.message)
const fields=computed(()=>Object.entries(props.schema.fields||{}).filter(([,s]:any)=>!Object.hasOwn(s,'fixed')&&!s.hidden) as [string,any][])
const rows=computed(()=>Array.isArray(props.modelValue)?props.modelValue.map((value:any,index:number)=>({value,index})).filter((r:any)=>JSON.stringify(r.value).toLowerCase().includes(search.value.toLowerCase())):[])
const pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/10)))
const addLabel=computed(()=>props.schema.newItemLabel?.startsWith('新增')?props.schema.newItemLabel:'新增'+(props.schema.newItemLabel||'項目'))
const asset=computed(()=>props.schema.format==='media'||['pdfUrl','brochureUrl'].includes(props.label||''))
const pdf=computed(()=>['pdfUrl','brochureUrl'].includes(props.label||'')||/PDF|型錄檔案/.test(title.value))
watch(search,()=>page.value=1)
watch(()=>errors.value,()=>{if(props.schema.type!=='array')return;const prefix=(props.path?props.path+'.':''),issue=errors.value?.find((e:any)=>e.documentId===props.documentId&&e.path.startsWith(prefix));const index=Number(issue?.path.slice(prefix.length).split('.')[0]);if(issue&&Number.isInteger(index)){openIndex.value=index;page.value=Math.floor(index/10)+1}},{deep:true})

function set(key:string,value:any){emit('update:modelValue',{...props.modelValue,[key]:value})}
function item(index:number,value:any){const a=[...(props.modelValue||[])];a[index]=value;emit('update:modelValue',a)}
function move(index:number,step:number){const a=[...(props.modelValue||[])];if(index+step<0||index+step>=a.length)return;[a[index],a[index+step]]=[a[index+step],a[index]];if(props.schema.source)a.forEach((v:any,i:number)=>v.sort=i);openIndex.value=index+step;emit('update:modelValue',a)}
function add(){const t=JSON.parse(JSON.stringify(props.schema.template??''));if(t&&typeof t==='object'&&!Array.isArray(t)){if('id'in t)t.id=props.schema.idGenerator==='store'?newStoreId(props.modelValue||[]):typeof t.id==='number'?Math.max(0,...(props.modelValue||[]).map((v:any)=>Number(v.id)||0))+1:crypto.randomUUID();if('slug'in t)t.slug='new-'+crypto.randomUUID().slice(0,8);if(t.summary)t.summary.title='新增內容';if('title'in t)t.title='新增內容';if('name'in t)t.name=props.schema.newItemLabel||'新增項目'}openIndex.value=props.modelValue?.length||0;emit('update:modelValue',[...(props.modelValue||[]),t]);search.value='';page.value=Math.ceil(((props.modelValue?.length||0)+1)/10);nextTick(()=>root.value?.querySelector<HTMLDetailsElement>('details[open]')?.scrollIntoView({block:'nearest'}))}
function remove(index:number){if(!window.confirm('移除此項目？儲存並更新官網後才會影響訪客看到的內容。'))return;emit('update:modelValue',props.modelValue.filter((_:any,i:number)=>i!==index));openIndex.value=null;page.value=Math.min(page.value,Math.max(1,Math.ceil((props.modelValue.length-1)/10)));nextTick(()=>root.value?.querySelector<HTMLElement>('summary')?.focus())}
function caption(value:any,index:number){return typeof value==='object'&&value?((props.schema.rowLabel&&value[props.schema.rowLabel])||rowName(value,index)):`${props.schema.item?.format==='media'?'圖片':'文字'} ${index+1}`}
function thumbnail(value:any){const image=value?.[props.schema.rowImage];return props.schema.rowImage?(Array.isArray(image)?image[0]:image):firstImage(value)}
function rowSchema(index:number){const s=props.schema.itemLabels?{...props.schema.item,label:props.schema.itemLabels[index]}:props.schema.item;if(!props.schema.source)return s;return{...s,fields:Object.fromEntries(Object.entries(s.fields).map(([k,v]:any)=>[k,{...v,...(['id','name'].includes(k)?{readOnly:true}:{} )}]))}}
</script>
<template>
 <AdminStoreRegions v-if="schema.editor==='store-regions'" :model-value="modelValue" @update:model-value="emit('update:modelValue',$event)" />
 <fieldset v-else-if="schema.type==='object'" class="cms-fields"><legend v-if="label">{{ title }}</legend><AdminHeroImages v-if="schema.editor==='hero-images'" :model-value="modelValue" :style="{'--hero-pan-x': Number(path?.split('.').at(-1)) % 2 === 1 ? '4%' : '-4%'}" @update:model-value="emit('update:modelValue',$event)" /><AdminStoreLocation v-if="schema.editor==='store-location'" :model-value="modelValue" @update:model-value="emit('update:modelValue',$event)" /><template v-for="[key,field] in fields" :key="key"><details v-if="key==='cmsSettings'||key==='seo'" class="cms-secondary"><summary>顯示與搜尋結果設定</summary><AdminFields :model-value="modelValue?.[key]" :schema="field" :document-id="documentId" :label="key" :path="`${path?path+'.':''}${key}`" @update:model-value="set(key,$event)" /></details><AdminFields v-else :model-value="modelValue?.[key]" :schema="field" :document-id="documentId" :label="key" :path="`${path?path+'.':''}${key}`" @update:model-value="set(key,$event)" /></template></fieldset>
 <AdminHomeCases v-else-if="schema.editor==='home-cases'" :model-value="modelValue" :label="title" :invalid="!!fieldError" @update:model-value="emit('update:modelValue',$event)" />
 <section v-else-if="schema.type==='array'" ref="root" class="cms-array"><div class="cms-section-heading"><strong>{{ title }} <span class="cms-count">{{ modelValue?.length||0 }}</span></strong><button v-if="!schema.source" type="button" class="cms-button" @click="add">{{ addLabel }}</button></div><p v-if="schema.help" class="cms-field-help cms-array-help">{{ schema.help }}</p><label v-if="(modelValue?.length||0)>10" class="cms-search"><input v-model="search" :aria-label="`搜尋${title}`" placeholder="搜尋名稱" /></label><details v-for="row in rows.slice((page-1)*10,page*10)" :key="row.value?.id??row.index" :name="hintId" :open="openIndex===row.index" class="cms-array-row" @toggle="($event.target as HTMLDetailsElement).open?openIndex=row.index:null"><summary><span class="cms-array-summary-content"><AdminImage v-if="thumbnail(row.value)" :src="thumbnail(row.value)" :alt="caption(row.value,row.index)+'縮圖'" class="cms-array-thumbnail" /><span>{{ caption(row.value,row.index) }}</span><small v-if="typeof row.value?.enabled==='boolean'" class="cms-status">{{ row.value.enabled?'官網顯示':'暫不顯示' }}</small></span></summary><template v-if="openIndex===row.index"><div class="cms-actions cms-item-tools"><button type="button" class="cms-button" :disabled="row.index===0" @click="move(row.index,-1)">往前移</button><button type="button" class="cms-button" :disabled="row.index===modelValue.length-1" @click="move(row.index,1)">往後移</button><button v-if="!schema.source" type="button" class="cms-button" :disabled="modelValue.length<=(schema.min||0)" @click="remove(row.index)">移除此項</button></div><AdminFields :model-value="row.value" :schema="rowSchema(row.index)" :document-id="documentId" :path="`${path?path+'.':''}${row.index}`" @update:model-value="item(row.index,$event)" /></template></details><p v-if="!rows.length" class="cms-empty">{{ modelValue?.length?'沒有符合的項目':'目前沒有內容，按上方按鈕新增。' }}</p><div v-if="pages>1" class="cms-actions cms-pagination"><button type="button" class="cms-button" :disabled="page===1" @click="page--">上一頁</button><span>{{ page }} / {{ pages }}</span><button type="button" class="cms-button" :disabled="page>=pages" @click="page++">下一頁</button></div></section>
 <div v-else-if="schema.enum" class="cms-field"><label :for="hintId+'-select'">{{ title }}</label><select :id="hintId+'-select'" :value="modelValue" :aria-describedby="hintId" :aria-invalid="!!fieldError" @change="emit('update:modelValue',($event.target as HTMLSelectElement).value)"><option v-if="schema.optionLabels&&!schema.enum.includes(modelValue)" :value="modelValue">目前自訂尺寸（保留）</option><option v-for="(v,index) in schema.enum" :key="v" :value="v">{{ schema.optionLabels?.[index]||({latest:'最新消息',activities:'優惠活動',video:'影片'} as any)[v]||v }}</option></select></div>
 <div v-else-if="schema.type==='boolean'" class="cms-field"><label class="cms-checkbox"><input type="checkbox" :checked="modelValue" :aria-describedby="hintId" :aria-invalid="!!fieldError" @change="emit('update:modelValue',($event.target as HTMLInputElement).checked)" />{{ title }}</label></div>
 <label v-else-if="schema.type==='number'" class="cms-field">{{ title }}<input type="number" :value="modelValue" :aria-invalid="!!fieldError" :aria-describedby="hintId" @input="emit('update:modelValue',Number(($event.target as HTMLInputElement).value))" /></label>
 <div v-else-if="asset" class="cms-field"><strong>{{ title }}</strong><AdminImage v-if="modelValue&&!pdf" :src="modelValue" :alt="title" class="cms-field-thumbnail" :class="{'cms-field-thumbnail-dark':schema.previewTone==='dark'}" /><p v-else class="cms-field-help">{{ modelValue?'已選擇 PDF 檔案':'尚未選擇'+(pdf?'檔案':'圖片') }}</p><button type="button" class="cms-button" @click="picker=true">{{ modelValue?'更換':'選擇或上傳' }}{{ pdf?'檔案':'圖片' }}</button><AdminDialog :open="picker" :title="pdf?'選擇 PDF 檔案':'選擇圖片'" wide @close="picker=false"><AdminMediaGrid picking :kind="pdf?'pdf':'image'" @select="emit('update:modelValue',$event.src);picker=false" /></AdminDialog></div>
 <AdminPageLink v-else-if="schema.format==='url'" :model-value="modelValue||''" :label="title" :invalid="!!fieldError" @update:model-value="emit('update:modelValue',$event)" />
 <div v-else class="cms-field"><label>{{ title }}<textarea v-if="!schema.format&&!schema.identity" :aria-describedby="hintId" :aria-invalid="!!fieldError" :readonly="schema.readOnly" :value="modelValue??''" rows="2" @input="emit('update:modelValue',($event.target as HTMLTextAreaElement).value)" /><input v-else :aria-describedby="hintId" :aria-invalid="!!fieldError" :readonly="schema.readOnly||schema.identity" :value="modelValue??''" @input="emit('update:modelValue',($event.target as HTMLInputElement).value)" /></label></div>
 <p v-if="fieldError||schema.help" :id="hintId" :class="fieldError?'cms-inline-error':'cms-field-help'" :role="fieldError?'alert':undefined">{{ fieldError||schema.help }}</p>
</template>
